import {base64url, fromBase64url} from '../agent/door-identity.mjs';
import {editorSecretUsable, editorSecretKeyMaterial} from './editor-keys.mjs';

export const SIGNED_ACCESS_SECONDS = 24 * 60 * 60;
const PREFIX = 'rpa1';
const DOMAIN = 'rapier-oauth-access-v1:';
const OWNER = /^owner_[A-Za-z0-9_-]{43}$/, CONNECTION = /^connection_[A-Za-z0-9_-]{43}$/;
const encoder = new TextEncoder(), decoder = new TextDecoder('utf-8', {fatal: true});
const keys = new Map();
async function key(secret) {
  if (!keys.has(secret)) keys.set(secret, crypto.subtle.importKey('raw', editorSecretKeyMaterial(secret, DOMAIN), {name: 'HMAC', hash: 'SHA-256'}, false, ['sign', 'verify']));
  return keys.get(secret);
}
export const isSignedAccessToken = token => typeof token === 'string' && token.startsWith(PREFIX + '.');

export async function mintAccessToken(secret, grant, {now = Date.now(), seconds = SIGNED_ACCESS_SECONDS} = {}) {
  if (!editorSecretUsable(secret)) throw new Error('EDITOR_KEY_SECRET must encode 32 generated bytes');
  const issued = Math.floor(now / 1000);
  const body = base64url(encoder.encode(JSON.stringify({o: grant.ownerId, c: grant.connectionId, g: grant.grantId, k: grant.clientId,
    a: grant.audience, s: grant.scopes, i: issued, x: issued + seconds, n: base64url(crypto.getRandomValues(new Uint8Array(12)))})));
  const mac = new Uint8Array(await crypto.subtle.sign('HMAC', await key(secret), encoder.encode(PREFIX + '.' + body)));
  return PREFIX + '.' + body + '.' + base64url(mac);
}

export async function verifyAccessToken(secret, token, {now = Date.now()} = {}) {
  if (!editorSecretUsable(secret) || !isSignedAccessToken(token) || token.length > 4096) return null;
  const parts = token.split('.');
  if (parts.length !== 3 || !/^[A-Za-z0-9_-]+$/.test(parts[1]) || !/^[A-Za-z0-9_-]{43}$/.test(parts[2])) return null;
  let mac; try { mac = fromBase64url(parts[2]); } catch { return null; }
  if (base64url(mac) !== parts[2] || !await crypto.subtle.verify('HMAC', await key(secret), mac, encoder.encode(PREFIX + '.' + parts[1]))) return null;
  let claims; try { claims = JSON.parse(decoder.decode(fromBase64url(parts[1]))); } catch { return null; }
  const at = Math.floor(now / 1000);
  if (!claims || typeof claims !== 'object' || !OWNER.test(claims.o) || !CONNECTION.test(claims.c) || !/^[A-Za-z0-9_-]{1,128}$/.test(claims.g) ||
      typeof claims.k !== 'string' || !claims.k || typeof claims.a !== 'string' || !Array.isArray(claims.s) || !claims.s.every(scope => typeof scope === 'string') ||
      !Number.isSafeInteger(claims.i) || !Number.isSafeInteger(claims.x) || claims.i > at + 60 || claims.x <= at) return null;
  return {ownerId: claims.o, connectionId: claims.c, grantId: claims.g, clientId: claims.k, audience: claims.a, scopes: [...claims.s], expiresAt: claims.x};
}
